<?php
/** Native resource-based desktop, mobile, footer and legal menus. */
if(PHP_SAPI!=='cli'||!in_array('--apply',$argv,true))exit("Usage: php tools/modx/configure-navigation.php --apply\n");
$root=dirname(__DIR__,2).'/';define('MODX_API_MODE',true);require $root.'public/index.php';$modx->initialize('mgr');
use MODX\Revolution\{modChunk,modResource,modCategory,modTemplateVar,modTemplateVarTemplate,modTemplateVarResource};
$header=$modx->getObject(modChunk::class,['name'=>'header']);$footer=$modx->getObject(modChunk::class,['name'=>'footer']);$mobile=$modx->getObject(modChunk::class,['name'=>'mobileMenu']);$initial=!str_contains($header->get('snippet'),'[[!pdoMenu?');
$icons=[5=>'navIconGlove',6=>'navIconPeople',3=>'navIconGym',7=>'navIconInfo'];
if($initial){$doc=new DOMDocument();libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8">'.$mobile->get('snippet'));libxml_clear_errors();$xp=new DOMXPath($doc);foreach($xp->query('//details[@class="mobile-section"]') as $section){$link=$xp->query('./summary/a',$section)->item(0);$r=$modx->getObject(modResource::class,['uri'=>ltrim(parse_url($link->getAttribute('href'),PHP_URL_PATH),'/'),'context_key'=>'web']);if(!$r||!isset($icons[$r->get('id')]))throw new RuntimeException('Original menu icon missing');$svg=$xp->query('.//span[@class="mobile-section-icon"]/svg',$link)->item(0);file_put_contents($root.'cms/chunks/'.$icons[$r->get('id')].'.html',str_replace('viewbox=','viewBox=',$doc->saveHTML($svg))."\n");}}
$category=$modx->getObject(modCategory::class,['category'=>'Навигация'])?:$modx->newObject(modCategory::class);$category->set('category','Навигация');if(!$category->save())throw new RuntimeException('Category save failed');
$tv=$modx->getObject(modTemplateVar::class,['name'=>'navigation_icon'])?:$modx->newObject(modTemplateVar::class);$tv->fromArray(['name'=>'navigation_icon','caption'=>'Иконка мобильного меню','description'=>'Иконка раздела в мобильном меню. Название — стандартный «Заголовок меню», порядок — menuindex, видимость — «Скрыть из меню».','category'=>$category->get('id'),'type'=>'listbox','elements'=>'Перчатка==navIconGlove||Люди==navIconPeople||Зал==navIconGym||Информация==navIconInfo','default_text'=>'navIconInfo','display'=>'default']);if(!$tv->save())throw new RuntimeException('TV save failed');$tvId=(int)$tv->get('id');
foreach($icons as $id=>$icon){$r=$modx->getObject(modResource::class,$id);$criteria=['tmplvarid'=>$tvId,'templateid'=>$r->get('template')];if(!$modx->getObject(modTemplateVarTemplate::class,$criteria)){$link=$modx->newObject(modTemplateVarTemplate::class);$link->fromArray($criteria,'',true,true);if(!$link->save())throw new RuntimeException('TV assignment failed');}if(!$modx->getObject(modTemplateVarResource::class,['tmplvarid'=>$tvId,'contentid'=>$id]))$r->setTVValue('navigation_icon',$icon);}
function menuCall($variant){
	$inner=$variant==='Footer'?'menuListWrapper':'menuPassThrough';
	return "[[!pdoMenu?\n".
		"\t&parents=`0`\n\t&level=`2`\n\t&resources=`-1,-2,-8,-9,-38,-39,-40`\n\t&context=`web`\n\t&where=`{\"class_key\":\"MODX\\\\Revolution\\\\modDocument\"}`\n".
		"\t&sortby=`menuindex`\n\t&sortdir=`ASC`\n\t&showHidden=`0`\n\t&showUnpublished=`0`\n\t&scheme=`abs`\n\t&cache=`0`\n\t&cacheAnonymous=`0`\n\t&hereClass=`is-active`\n\t&selfClass=`is-current`\n\t&includeTVs=`navigation_icon`\n\t&tvPrefix=``\n".
		"\t&tplOuter=`menuPassThrough`\n\t&tplInner=`$inner`\n\t&tpl=`menu{$variant}Leaf`\n\t&tplHere=`menu{$variant}Leaf`\n\t&tplParentRow=`menu{$variant}Parent`\n\t&tplParentRowHere=`menu{$variant}Parent`\n\t&tplParentRowActive=`menu{$variant}Parent`\n\t&tplInnerRow=`menu{$variant}Child`\n\t&tplInnerHere=`menu{$variant}Child`\n]]";
}
if($initial){
	// Standard resource order is shared by all three menus and catalogue cards.
	foreach([5,6,3,7] as $index=>$id){$r=$modx->getObject(modResource::class,$id);$r->set('menuindex',$index+1);$r->save();}
	$r=$modx->getObject(modResource::class,29);if(!$r->get('menutitle')){$r->set('menutitle','FAQ');$r->save();}
	foreach([[$header,'desktop-nav','Desktop'],[$footer,'footer-navigation','Footer'],[$mobile,'mobile-navigation','Mobile']] as [$chunk,$class,$variant]){$s=$chunk->get('snippet');$s=preg_replace('~(<nav class="'.$class.'"[^>]*>).*?(</nav>)~s','$1'."\n".menuCall($variant)."\n".'$2',$s,1,$count);if($count!==1)throw new RuntimeException('Menu location missing');$s=str_replace('href="/"','href="[[~1? &scheme=`abs`]]"',$s);$s=str_replace('href="/info/contacts/#organization-title"','href="[[~27? &scheme=`abs`]]#organization-title"',$s);
		if($variant==='Footer'){$legal="[[!pdoMenu?\n\t&parents=`0`\n\t&level=`1`\n\t&resources=`8,9`\n\t&context=`web`\n\t&sortby=`menuindex`\n\t&sortdir=`ASC`\n\t&showHidden=`0`\n\t&scheme=`abs`\n\t&cache=`0`\n\t&cacheAnonymous=`0`\n\t&tplOuter=`menuPassThrough`\n\t&tpl=`menuLegalItem`\n\t&tplHere=`menuLegalItem`\n]]";$s=preg_replace('~(<nav aria-label="Правовая информация">).*?(</nav>)~s','$1'."\n".$legal."\n".'$2',$s,1);}
		$chunk->set('snippet',$s);if(!$chunk->save())throw new RuntimeException('Shared chunk save failed');file_put_contents($root.'cms/chunks/'.$chunk->get('name').'.html',$s);
	}
}
$names=['menuPassThrough','menuListWrapper','menuDesktopParent','menuDesktopLeaf','menuDesktopChild','menuMobileParent','menuMobileLeaf','menuMobileChild','menuFooterParent','menuFooterLeaf','menuFooterChild','menuLegalItem',...array_values($icons)];$common=$modx->getObject(modCategory::class,['category'=>'Общие']);foreach($names as $name){$c=$modx->getObject(modChunk::class,['name'=>$name])?:$modx->newObject(modChunk::class);$c->fromArray(['name'=>$name,'category'=>$common->get('id'),'snippet'=>file_get_contents($root.'cms/chunks/'.$name.'.html')]);if(!$c->save())throw new RuntimeException('Menu chunk save failed');}
$file=$root.'cms/template-registry.json';$reg=json_decode(file_get_contents($file),true);$reg['fields']['navigation_icon']=$tvId;$reg['chunks']=array_values(array_unique(array_merge($reg['chunks'],$names)));file_put_contents($file,json_encode($reg,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$modx->cacheManager->refresh();echo "Native pdoMenu navigation applied to desktop/footer/mobile/legal.\n";
